(function(){
  const DB=()=>typeof db!=='undefined'?db:null;
  const $=id=>document.getElementById(id);
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const norm=v=>String(v||'').trim().toLowerCase();
  let open=false,submitting=false,pendingSubmission=null;

  function candidates(){
    const store=DB();
    return (store?.candidates||[]).slice().sort((a,b)=>String(a.name||a.candidate_name||'').localeCompare(String(b.name||b.candidate_name||'')));
  }
  function requirements(){
    const store=DB();
    return (store?.requirements||[]).filter(r=>!['closed','fulfilled'].includes(norm(r.status))).slice().sort((a,b)=>`${a.client} ${a.title}`.localeCompare(`${b.client} ${b.title}`));
  }
  function reqKey(r){return String(r.serverId||r.id||r.profileKey||'')}
  function candKey(c){return String(c.serverId||c.id||c.email||c.name||'')}
  function formatReq(r){return `${r.id||''} · ${r.title||'Position'} — ${r.client||'Client'}`}
  function emailOf(c){return c?.email||c?.candidate_email||''}
  function nameOf(c){return c?.name||c?.candidate_name||'Candidate'}

  function ensureModal(){
    if($('tssInterviewSchedulerModal'))return;
    const wrap=document.createElement('div');
    wrap.id='tssInterviewSchedulerModal';
    wrap.className='tss-is-modal hidden';
    wrap.innerHTML=`<div class="tss-is-card" role="dialog" aria-modal="true" aria-labelledby="tssIsTitle">
      <div class="tss-is-head"><div><small>TODO AI · INTERVIEW OPERATIONS</small><h2 id="tssIsTitle">Schedule Interview</h2></div><button type="button" data-is-close aria-label="Close">×</button></div>
      <div class="tss-is-grid">
        <label class="tss-is-full"><span>Candidate <b>*</b></span><select id="tssIsCandidate"></select><small id="tssIsCandidateMeta"></small></label>
        <label class="tss-is-full"><span>Position / Requirement <b>*</b></span><select id="tssIsRequirement"></select><small id="tssIsReqMeta"></small></label>
        <label><span>Date <b>*</b></span><input id="tssIsDate" type="date"></label>
        <label><span>Time <b>*</b></span><input id="tssIsTime" type="time" value="11:00"></label>
        <label><span>Mode</span><select id="tssIsMode"><option>Client Interview</option><option>Video Interview</option><option>Telephonic Interview</option><option>Face to Face</option></select></label>
        <label><span>Interviewer</span><input id="tssIsInterviewer" placeholder="Optional"></label>
        <label class="tss-is-full"><span>Interview Link / Location</span><input id="tssIsLocation" placeholder="Teams/Meet link or office location"></label>
        <label class="tss-is-full"><span>Notes</span><textarea id="tssIsNotes" rows="3" placeholder="Optional instructions"></textarea></label>
      </div>
      <div class="tss-is-warning">The confirmation email will use the exact candidate and requirement selected here. Please verify both before scheduling.</div>
      <div class="tss-is-actions"><button type="button" data-is-close class="secondary">Cancel</button><button type="button" id="tssIsSubmit">Schedule & Send Confirmation</button></div>
    </div>`;
    document.body.appendChild(wrap);
    const style=document.createElement('style');
    style.textContent=`.tss-is-modal{position:fixed;inset:0;z-index:100000;background:rgba(2,11,20,.76);display:grid;place-items:center;padding:22px}.tss-is-modal.hidden{display:none}.tss-is-card{width:min(760px,96vw);max-height:92vh;overflow:auto;background:#0c2235;border:1px solid #2e5878;border-radius:18px;box-shadow:0 28px 80px rgba(0,0,0,.45);color:#eef7ff;padding:24px}.tss-is-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:20px}.tss-is-head small{color:#65bfff;font-weight:800;letter-spacing:1.4px}.tss-is-head h2{margin:6px 0 0;font-size:25px}.tss-is-head button{border:0;background:transparent;color:#bdd5e7;font-size:30px;cursor:pointer}.tss-is-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.tss-is-grid label{display:flex;flex-direction:column;gap:7px}.tss-is-grid label span{font-weight:750;font-size:13px;color:#d5e7f5}.tss-is-grid label span b{color:#ff9b9b}.tss-is-grid input,.tss-is-grid select,.tss-is-grid textarea{width:100%;box-sizing:border-box;border:1px solid #315b79;border-radius:10px;background:#081a29;color:#f5fbff;padding:11px 12px;font:inherit;outline:none}.tss-is-grid input:focus,.tss-is-grid select:focus,.tss-is-grid textarea:focus{border-color:#35a8ff;box-shadow:0 0 0 3px rgba(53,168,255,.12)}.tss-is-grid label small{min-height:16px;color:#8fb2ca;font-size:11px}.tss-is-full{grid-column:1/-1}.tss-is-warning{margin-top:16px;padding:11px 13px;border-radius:10px;background:#102f46;border:1px solid #2e648b;color:#bcdcf2;font-size:12px;line-height:1.45}.tss-is-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}.tss-is-actions button{border:1px solid #1987d8;background:#1987d8;color:white;border-radius:10px;padding:11px 16px;font-weight:800;cursor:pointer}.tss-is-actions button:disabled{opacity:.6;cursor:wait}.tss-is-actions button.secondary{background:transparent;border-color:#3a6079;color:#c6d9e7}@media(max-width:700px){.tss-is-grid{grid-template-columns:1fr}.tss-is-full{grid-column:auto}.tss-is-card{padding:18px}}`;
    document.head.appendChild(style);
    wrap.addEventListener('click',e=>{if(e.target===wrap||e.target.closest('[data-is-close]'))closeModal()});
    $('tssIsCandidate')?.addEventListener('change',updateCandidateMeta);
    $('tssIsRequirement')?.addEventListener('change',updateReqMeta);
    $('tssIsSubmit')?.addEventListener('click',submit);
  }

  function populate(){
    const cs=candidates(),rs=requirements();
    const csel=$('tssIsCandidate'),rsel=$('tssIsRequirement');
    csel.innerHTML=cs.length?'<option value="">Select saved candidate…</option>'+cs.map(c=>`<option value="${esc(candKey(c))}">${esc(nameOf(c))}${emailOf(c)?` — ${esc(emailOf(c))}`:''}</option>`).join(''):'<option value="">No saved candidates found</option>';
    rsel.innerHTML=rs.length?'<option value="">Select position / requirement…</option>'+rs.map(r=>`<option value="${esc(reqKey(r))}">${esc(formatReq(r))}</option>`).join(''):'<option value="">No open requirements found</option>';
    const current=DB()?.requirements?.find(r=>String(r.id)===$('screenRequirement')?.value);
    if(current&&rs.some(r=>reqKey(r)===reqKey(current)))rsel.value=reqKey(current);
    $('tssIsDate').value=new Date().toISOString().slice(0,10);
    updateCandidateMeta();updateReqMeta();
  }
  function selectedCandidate(){const key=$('tssIsCandidate')?.value;return candidates().find(c=>candKey(c)===key)}
  function selectedRequirement(){const key=$('tssIsRequirement')?.value;return requirements().find(r=>reqKey(r)===key)}
  function updateCandidateMeta(){const c=selectedCandidate();$('tssIsCandidateMeta').textContent=c?`${emailOf(c)||'No email saved'}${c.phone?` · ${c.phone}`:''}`:'Choose a candidate already saved in Candidate Records.'}
  function updateReqMeta(){const r=selectedRequirement();$('tssIsReqMeta').textContent=r?`${r.status||''}${r.location?` · ${r.location}`:''}${r.positionsCount||r.positions_count?` · ${r.positionsCount||r.positions_count} position(s)`:''}`:'The selected requirement controls the role/client shown in the email.'}
  function openModal(){ensureModal();populate();pendingSubmission=null;$('tssInterviewSchedulerModal').classList.remove('hidden');open=true}
  function closeModal(){$('tssInterviewSchedulerModal')?.classList.add('hidden');open=false}
  function localTimeLabel(value){if(!value)return'';const [h0,m='00']=value.split(':');let h=Number(h0),ap=h>=12?'PM':'AM';h=h%12||12;return `${h}:${m} ${ap}`}
  async function submit(){
    if(submitting)return;
    const c=selectedCandidate(),r=selectedRequirement();
    const date=$('tssIsDate').value,time=$('tssIsTime').value;
    if(!c)return alert('Please select a saved candidate.');
    if(!r)return alert('Please select the exact position / requirement.');
    if(!date||!time)return alert('Please select interview date and time.');
    if(!emailOf(c))return alert('This candidate has no email saved. Add the candidate email first so confirmation can be sent.');
    const store=DB(); if(!store)return;
    const item={candidate:nameOf(c),email:emailOf(c),candidateId:c.serverId||c.id||null,date,time:localTimeLabel(time),position:r.title||'',client:r.client||'',requirementId:r.id||'',requirementServerId:r.serverId||null,mode:$('tssIsMode').value||'Client Interview',interviewer:$('tssIsInterviewer').value.trim(),locationOrLink:$('tssIsLocation').value.trim(),notes:$('tssIsNotes').value.trim()};
    const submissionKey=JSON.stringify([item.candidateId,item.requirementServerId,item.date,item.time,item.mode,item.interviewer,item.locationOrLink,item.notes]);
    if(pendingSubmission?.submissionKey===submissionKey)item.clientRequestId=pendingSubmission.item.clientRequestId;
    else item.clientRequestId=window.TSSInterviewSync?.newRequestId?.();
    const confirmation=`Schedule interview?\n\nCandidate: ${item.candidate}\nPosition: ${item.position}\nClient: ${item.client}\nDate: ${item.date}\nTime: ${item.time}\n\nThe email will be sent using THIS exact position.`;
    if(!confirm(confirmation))return;
    const button=$('tssIsSubmit'),originalText=button?.textContent||'Schedule & Send Confirmation';
    submitting=true;pendingSubmission={submissionKey,item};
    if(button){button.disabled=true;button.textContent='Scheduling…'}
    try{
      if(!window.TSSInterviewSync?.persistItem)throw new Error('Interview sync is not ready. Please refresh and try again.');
      await window.TSSInterviewSync.persistItem(item);
      store.interviews=store.interviews||[];
      if(!store.interviews.some(existing=>String(existing.serverId||existing.id)===String(item.serverId)))store.interviews.push(item);
      localStorage.setItem('tss_talent_buddy_v1',JSON.stringify(store));
      pendingSubmission=null;closeModal();
      try{window.TSSInterviewActions?.renderStable?.(true)}catch{}
      try{toast(`Interview scheduled for ${item.position} · confirmation + reminders queued`)}catch{}
    }catch(error){
      item.syncState='failed';item.syncError=error?.message||String(error);console.warn(error);
      try{toast('Interview was not scheduled: '+item.syncError)}catch{}
    }finally{
      submitting=false;if(button){button.disabled=false;button.textContent=originalText}
    }
  }

  function intercept(e){
    const btn=e.target.closest?.('#scheduleInterview');
    if(!btn)return;
    e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();openModal();
  }
  document.addEventListener('click',intercept,true);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ensureModal,{once:true});else ensureModal();
  window.TSSInterviewScheduler={open:openModal,close:closeModal,populate};
})();

/* ===== stable-runtime.js ===== */
// Stability-first runtime for TSS Resume Intelligence.
(function(){
  const $=id=>document.getElementById(id);
  const backend=()=>window.TSSBackend;
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  let booted=false;

  function renameUI(){
    document.querySelectorAll('.nav-item').forEach(b=>{if(b.dataset.view==='requirements'){const count=b.querySelector('b')?.outerHTML||'';b.innerHTML=`<span>▣</span>Requirements ${count}`;}});
    document.querySelectorAll('*').forEach(el=>{
      if(el.children.length===0&&el.textContent==='Active Job Profiles')el.textContent='Active Requirements';
    });
    const search=$('requirementSidebarSearch');if(search)search.placeholder='Search TSS ID or requirement';
  }

  function makeSidebarUsable(){
    const side=document.querySelector('.sidebar');
    const tree=$('clientRequirementTree');
    if(side){side.style.overflow='hidden';side.style.minHeight='0'}
    if(tree){tree.style.overflowY='auto';tree.style.overflowX='hidden';tree.style.minHeight='160px';tree.style.flex='1 1 auto';tree.style.maxHeight='calc(100vh - 560px)';tree.style.paddingRight='6px'}
  }

  async function refreshFromSupabase(){
    if(!backend()?.enabled)return;
    const user=await backend().currentUser().catch(()=>null);if(!user)return;
    const c=backend().client;
    const {data:reqs,error}=await c.from('requirements').select('*,clients(name)').neq('status','Closed').order('tss_id');
    if(error)throw error;
    if(Array.isArray(reqs)){
      db.requirements=reqs.map(row=>({
        id:row.profile_key||row.tss_id, requirementId:row.tss_id, profileKey:row.profile_key, serverId:row.id,
        client:row.clients?.name||'Client', clientOwner:row.client_owner||'', title:row.job_title,
        location:row.location||'Not provided', experience:row.experience_text||'Not provided',
        salaryRange:row.salary_range||'Not provided', industry:row.industry||'', qualification:row.qualification||'',
        responsibilities:row.responsibilities||'', jdText:row.jd_text||'', status:row.status||'Active',
        skills:row.mandatory_skills||[], preferred:row.preferred_skills||[],
        aiSuggested:Boolean(row.ai_suggested_skills?.length&&!row.ai_skills_approved)
      }));
      localStorage.setItem('tss_talent_buddy_v1',JSON.stringify(db));
      try{renderAll()}catch{}
      try{renderOldSite()}catch{}
      window.TSSRequirementStatusVisibility?.updateRemainingCount();
    }
  }

  async function logout(){
    return window.TSSAuth?.signOut?.();
  }

  function ensureLogout(){
    const top=$('signOutBtn');if(top)top.title='Logout';
    if(!$('sidebarLogout')){
      const b=document.createElement('button');b.id='sidebarLogout';b.className='add-client-btn';b.style.marginTop='4px';b.textContent='↪  Logout';b.onclick=logout;
      const note=document.querySelector('.workspace-note');note?.after(b);
    }
  }

  function ensureOwnerField(){
    if($('reqClientOwner'))return;
    const client=$('reqClient')?.closest('div');if(!client)return;
    const wrap=document.createElement('div');wrap.innerHTML='<label>Client Owner / Account Owner</label><input id="reqClientOwner" placeholder="Type recruiter / account owner name" />';
    client.after(wrap);
  }

  function ensureDetailsDialog(){
    if($('requirementDetailsDialog'))return;
    const d=document.createElement('dialog');d.id='requirementDetailsDialog';d.className='requirement-details-dialog';d.innerHTML=`<div class="req-detail-shell"><div class="dialog-head"><div><span class="purple-label">REQUIREMENT DETAILS</span><h3 id="reqDetailTitle">Requirement</h3></div><button id="closeReqDetails" class="icon-btn">×</button></div><div id="reqDetailBody"></div><div class="dialog-actions"><button id="reqDetailEdit" class="btn ghost">Edit Requirement</button><button id="reqDetailScreen" class="btn primary">Screen Candidate</button></div></div>`;document.body.appendChild(d);$('closeReqDetails').onclick=()=>d.close();
  }

  function openDetails(r){
    ensureDetailsDialog();if(!r)return;
    $('reqDetailTitle').textContent=`${r.requirementId||r.id} · ${r.title}`;
    const chips=a=>(a||[]).length?(a||[]).map(x=>`<span class="skill">${esc(x)}</span>`).join(''):'<span class="muted">Not provided</span>';
    $('reqDetailBody').innerHTML=`<div class="req-detail-grid"><div><span>Client</span><strong>${esc(r.client)}</strong></div><div><span>Client Owner</span><strong>${esc(r.clientOwner||'Not assigned')}</strong></div><div><span>Location</span><strong>${esc(r.location||'Not provided')}</strong></div><div><span>Experience</span><strong>${esc(r.experience||'Not provided')}</strong></div><div><span>Salary / Budget</span><strong>${esc(r.salaryRange||'Not provided')}</strong></div><div><span>Qualification</span><strong>${esc(r.qualification||'Not provided')}</strong></div></div><h4>Mandatory Skills</h4><div class="skill-cloud">${chips(r.skills)}</div><h4>Preferred Skills</h4><div class="skill-cloud">${chips(r.preferred)}</div><h4>Roles & Responsibilities / JD</h4><div class="req-detail-text">${esc(r.responsibilities||r.jdText||'Not provided')}</div>`;
    $('reqDetailEdit').onclick=()=>{ $('requirementDetailsDialog').close(); try{openRequirement(r.id)}catch{} };
    $('reqDetailScreen').onclick=()=>{ $('requirementDetailsDialog').close(); if($('screenRequirement'))$('screenRequirement').value=r.id; try{updateSelectedRequirement()}catch{}; try{gotoView('screening')}catch{} };
    $('requirementDetailsDialog').showModal();
  }

  function wireRequirementClicks(){
    document.addEventListener('click',e=>{
      const role=e.target.closest('.client-role');
      if(role){e.preventDefault();e.stopPropagation();const key=role.dataset.id||role.dataset.req||role.getAttribute('data-requirement');const text=role.innerText;const r=(db.requirements||[]).find(x=>x.id===key)||(db.requirements||[]).find(x=>text.includes(x.requirementId||x.id)&&text.includes(x.title));if(r)openDetails(r);return;}
      const card=e.target.closest('#requirementCards .req-card');
      if(card&&!e.target.closest('button,input,select,textarea')){const edit=card.querySelector('[data-id]');const key=edit?.dataset.id;const r=(db.requirements||[]).find(x=>x.id===key);if(r)openDetails(r)}
    },true);
  }

  async function saveOwnerFromDialog(){
    const id=$('reqId')?.value;const r=(db.requirements||[]).find(x=>x.id===id);if(!r)return;
    r.clientOwner=$('reqClientOwner')?.value.trim()||'';
    if(r.serverId&&backend()?.enabled){const {error}=await backend().client.from('requirements').update({client_owner:r.clientOwner,updated_at:new Date().toISOString()}).eq('id',r.serverId);if(error)throw error;}
  }

  function wireOwnerSave(){
    const save=$('saveRequirementBtn');if(!save||save.dataset.stableOwner)return;save.dataset.stableOwner='1';save.addEventListener('click',()=>setTimeout(()=>saveOwnerFromDialog().catch(e=>console.warn('Owner save',e)),250));
    const dialog=$('requirementDialog');dialog?.addEventListener('close',()=>{const id=$('reqId')?.value;const r=(db.requirements||[]).find(x=>x.id===id);if(r&&$('reqClientOwner'))$('reqClientOwner').value=r.clientOwner||''});
  }

  function css(){
    if($('stableRuntimeStyle'))return;const s=document.createElement('style');s.id='stableRuntimeStyle';s.textContent=`
      .client-tree{scrollbar-width:thin;scrollbar-color:#2b79b5 transparent}.client-tree::-webkit-scrollbar{width:8px}.client-tree::-webkit-scrollbar-thumb{background:#235f8d;border-radius:8px}
      #sidebarLogout{width:100%;border-color:#5d3140;color:#ffd6df;background:#2a1720}.requirement-details-dialog{width:min(900px,92vw);max-height:88vh;border:1px solid #28506f;border-radius:16px;background:#081725;color:#eef7ff;padding:0}.req-detail-shell{padding:22px}.req-detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:16px 0}.req-detail-grid>div{border:1px solid #1d3d58;background:#0b2032;padding:14px;border-radius:10px}.req-detail-grid span{display:block;color:#8aa8c3;font-size:12px;margin-bottom:5px}.req-detail-grid strong{font-size:15px}.req-detail-shell h4{margin:18px 0 9px}.req-detail-text{white-space:pre-wrap;line-height:1.6;color:#bdd0df;border:1px solid #1d3d58;background:#091b2b;border-radius:10px;padding:14px;max-height:240px;overflow:auto}@media(max-width:700px){.req-detail-grid{grid-template-columns:1fr}}
    `;document.head.appendChild(s);
  }

  async function boot(){if(booted)return;booted=true;css();renameUI();makeSidebarUsable();ensureLogout();ensureOwnerField();ensureDetailsDialog();wireRequirementClicks();wireOwnerSave();renameUI();makeSidebarUsable();}

  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(boot,300));else setTimeout(boot,300);
  window.TSSStableRuntime={boot,refreshFromSupabase,openDetails,logout};
})();

/* ===== requirement-status-visibility.js ===== */
// Remaining requirements include every open status; fulfilled and closed are review-only.
(function(){
  const $=id=>document.getElementById(id);
  const norm=s=>String(s||'').trim().toLowerCase();
  const remainingStatus=s=>['active','work in progress','on hold'].includes(norm(s));

  function openRequirements(){
    if(typeof db==='undefined' || !Array.isArray(db.requirements)) return [];
    return db.requirements.filter(r=>remainingStatus(r.status));
  }

  // Legacy renderers use activeReqs() for sidebar, selectors and counts.
  // Active, WIP and On Hold requirements must remain visible in operational views.
  window.activeReqs=openRequirements;

  function ensureStatusOptions(){
    const reqStatus=$('reqStatus');
    if(reqStatus){
      const current=reqStatus.value;
      reqStatus.innerHTML=`
        <option value="Work In Progress">Work In Progress</option>
        <option value="On Hold">On Hold</option>
        <option value="Closed">Closed</option>
        <option value="Fulfilled">Joined TSS</option>`;
      reqStatus.value=['Work In Progress','On Hold','Closed','Fulfilled'].includes(current)?current:'Work In Progress';
    }
  }

  function ensureFilter(){
    let select=$('requirementStatusFilter');
    if(!select){
      const row=document.querySelector('#requirements .filter-row');
      if(!row) return null;
      select=document.createElement('select');
      select.id='requirementStatusFilter';
      select.setAttribute('aria-label','Filter requirements by status');
      row.appendChild(select);
      select.addEventListener('change',applyStatusFilter);
    }
    const current=select.value;
    select.innerHTML=`
      <option value="Remaining">Remaining Requirements</option>
      <option value="Work In Progress">Work In Progress</option>
      <option value="On Hold">On Hold</option>
      <option value="Closed">Closed</option>
      <option value="Fulfilled">Joined TSS</option>`;
    select.value=['Remaining','Work In Progress','On Hold','Closed','Fulfilled'].includes(current)?current:'Remaining';
    return select;
  }

  function requirementForCard(card){
    const id=card.querySelector('[data-id]')?.dataset?.id || card.dataset?.id;
    if(id && typeof db!=='undefined') return (db.requirements||[]).find(r=>r.id===id || r.requirementId===id);
    const txt=(card.textContent||'').toLowerCase();
    return (typeof db!=='undefined'?db.requirements:[]).find(r=>txt.includes(String(r.requirementId||r.id||'').toLowerCase()) && txt.includes(String(r.title||'').toLowerCase()));
  }

  function applyStatusFilter(){
    const chosen=norm($('requirementStatusFilter')?.value||'Remaining');
    const query=norm($('jobProfileSearch')?.value);
    const client=norm($('clientFilter')?.value);
    const location=norm($('locationFilter')?.value);
    document.querySelectorAll('#requirementCards .req-card').forEach(card=>{
      const r=requirementForCard(card);
      if(!r)return;
      const status=norm(r.status);
      const statusMatch=chosen==='remaining'?remainingStatus(status):
        chosen==='work in progress'?['active','work in progress'].includes(status):status===chosen;
      const text=norm(`${r.id} ${r.requirementId||''} ${r.client} ${r.title} ${r.location} ${(r.skills||[]).join(' ')}`);
      const matches=statusMatch&&(!query||text.includes(query))&&(!client||norm(r.client)===client)&&(!location||norm(r.location)===location);
      const display=matches?'block':'none';
      if(card.style.display!==display)card.style.display=display;
    });
    updateRemainingCount();
  }

  function updateRemainingCount(){
    const remaining=openRequirements();
    const n=remaining.length;
    const positions=remaining.reduce((sum,r)=>sum+(Number(r.positionsCount||r.positions_count)||0),0);
    if($('navReqCount'))$('navReqCount').textContent=String(n);
    if($('clientReqCount'))$('clientReqCount').textContent=String(n);
    if($('activeReqChip'))$('activeReqChip').textContent=`${n} remaining requirements · ${positions} positions`;
  }

  function refresh(){
    ensureStatusOptions();
    ensureFilter();
    try{if(typeof renderAll==='function')renderAll()}catch(e){console.warn('TODO AI status visibility renderAll',e)}
    try{if(typeof renderOldSite==='function')renderOldSite()}catch(e){console.warn('TODO AI status visibility renderOldSite',e)}
    applyStatusFilter();
  }

  function observe(){
    const cards=$('requirementCards');
    if(!cards || cards.dataset.statusObserver==='1') return;
    cards.dataset.statusObserver='1';
    new MutationObserver(applyStatusFilter).observe(cards,{childList:true});
  }

  function boot(){refresh();observe();setTimeout(()=>{ensureFilter();applyStatusFilter();observe()},250)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();

  window.TSSRequirementStatusVisibility={openRequirements,refresh,applyStatusFilter,ensureFilter,updateRemainingCount};
})();

/* ===== requirements-live-sync.js ===== */
// TODO AI authoritative open requirement sync. Supabase is source of truth.
(function(){
  const $=id=>document.getElementById(id);
  let finished=false,running=false;
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const backend=()=>window.TSSBackend;
  const serverKey=row=>row.profile_key||`${row.tss_id}::${row.job_title}`;

  function findLocal(row,locals){
    return locals.find(r=>(r.profileKey&&r.profileKey===row.profile_key)||((r.requirementId||r.id)===row.tss_id&&String(r.title||'').trim()===String(row.job_title||'').trim()));
  }
  function internalId(row,local){
    if(local?.id)return local.id;
    if(row.tss_id==='TSS040'&&/service engineer/i.test(row.job_title||''))return 'TSS040__INTELMAC';
    if(row.tss_id==='TSS040')return 'TSS040__NEOSOFT';
    return row.tss_id;
  }
  function mapRow(row,locals){
    const local=findLocal(row,locals)||{};
    return {...local,
      id:internalId(row,local),requirementId:row.tss_id,profileKey:serverKey(row),serverId:row.id,
      client:row.clients?.name||local.client||'Client',clientOwner:row.client_owner||'',
      requirementHandler:row.requirement_handler||local.requirementHandler||'',
      assignedRecruiters:Array.isArray(row.assigned_recruiters)?row.assigned_recruiters:[],
      createdAt:row.created_at||local.createdAt||null,updatedAt:row.updated_at||local.updatedAt||null,
      submittedAt:row.submitted_at||null,submittedBy:row.submitted_by||null,
      title:row.job_title||local.title||'Untitled Requirement',location:row.location||local.location||'Not provided',
      experience:row.experience_text||local.experience||'Not provided',positionsCount:row.positions_count??local.positionsCount??null,
      salaryRange:row.salary_range||local.salaryRange||'Not provided',
      industry:row.industry||local.industry||'',qualification:row.qualification||local.qualification||'Not provided',
      responsibilities:row.responsibilities||local.responsibilities||'',jdText:row.jd_text||local.jdText||'',status:row.status||local.status||'Active',
      skills:Array.isArray(row.mandatory_skills)&&row.mandatory_skills.length?row.mandatory_skills:(local.skills||[]),
      preferred:Array.isArray(row.preferred_skills)&&row.preferred_skills.length?row.preferred_skills:(local.preferred||[]),
      aiSuggested:Boolean(row.ai_suggested_skills?.length&&!row.ai_skills_approved)
    };
  }
  function paint(rows){
    window.TSSRequirementStatusVisibility?.updateRemainingCount();
  }
  function rerender(){
    try{if(typeof renderAll==='function')renderAll()}catch(e){console.warn('TODO AI renderAll',e)}
    try{if(typeof renderOldSite==='function')renderOldSite()}catch(e){console.warn('TODO AI renderOldSite',e)}
  }

  async function syncNow(){
    if(running||!backend()?.enabled||typeof db==='undefined')return false;
    running=true;
    try{
      const c=backend().client;
      const {data:{session},error:sessionError}=await c.auth.getSession();
      if(sessionError||!session?.user)return false;
      // Keep Active and On Hold requirements in the workspace. Closed requirements are excluded.
      const {data:reqs,error}=await c.from('requirements').select('*,clients(name)').neq('status','Closed').order('created_at',{ascending:false}).order('tss_id',{ascending:false});
      if(error)throw error;
      if(!Array.isArray(reqs))return false;
      console.info('TODO AI non-closed requirements returned:',reqs.length);
      const locals=Array.isArray(db.requirements)?db.requirements:[];
      const rows=reqs.map(row=>mapRow(row,locals));
      db.requirements=rows;
      try{localStorage.setItem('tss_talent_buddy_v1',JSON.stringify(db))}catch{}
      rerender();
      paint(rows);
      finished=true;
      console.info('TODO AI non-closed requirements hydrated:',rows.length);
      return true;
    }finally{running=false;}
  }

  async function boot(){
    const delays=[0,150,350,700,1200,2000,3200];
    for(const delay of delays){
      if(finished)break;
      if(delay)await sleep(delay);
      try{if(await syncNow())break}catch(e){console.warn('TODO AI requirement sync retry',e?.message||e)}
    }
  }

  // Realtime coordinator owns startup and reconnect refreshes. Keeping this module
  // callable avoids competing fetch/render loops during page boot.
  window.TSSRequirementsLiveSync={syncNow,boot,mapRow};
})();

