      if($('adminActiveUsers'))$('adminActiveUsers').textContent=String(users.filter(x=>x.is_active).length);
      if($('adminTotalAdmins'))$('adminTotalAdmins').textContent=String(users.filter(x=>String(x.role||'').toLowerCase()==='admin').length);
