/* ===== quick-screening.js ===== */
(function(){
  const byId=id=>document.getElementById(id);
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  let quickFile=null;

  function activeRequirements(){
    try{return (db.requirements||[]).filter(r=>['active','work in progress','on hold'].includes(String(r.status||'').trim().toLowerCase()))}catch{return []}
  }
  function selectedRequirement(){
    const id=byId('quickRequirement')?.value;
    try{return (db.requirements||[]).find(r=>String(r.id)===String(id))||null}catch{return null}
  }
  function setStatus(text,cls=''){
    const el=byId('quickScreenStatus'); if(!el)return;
    el.textContent=text; el.className=`quick-screen-status ${cls}`.trim();
  }
  function populateQuickRequirements(){
    const select=byId('quickRequirement'); if(!select)return;
    const current=select.value||byId('screenRequirement')?.value||byId('topRequirementSelect')?.value;
    const items=activeRequirements();
    select.innerHTML=items.map(r=>`<option value="${esc(r.id)}">${esc(r.title)} — ${esc(r.client)}</option>`).join('');
    if(current&&items.some(r=>String(r.id)===String(current)))select.value=current;
  }
  function deriveNameFromFilename(name=''){
    return name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').replace(/\b(cv|resume|profile|updated|latest|final)\b/ig,' ').replace(/\s+/g,' ').trim().replace(/\b\w/g,c=>c.toUpperCase());
  }
  function syncRequirementToCore(){
    const id=byId('quickRequirement')?.value; if(!id)return;
    const s=byId('screenRequirement'),t=byId('topRequirementSelect');
    if(s){s.value=id;s.dispatchEvent(new Event('change',{bubbles:true}))}
    if(t){t.value=id;t.dispatchEvent(new Event('change',{bubbles:true}))}
  }
  async function feedFileToCore(file){
    const input=byId('resumeFile'); if(!input||!file)return false;
    try{
      const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;
      input.dispatchEvent(new Event('change',{bubbles:true}));
      return true;
    }catch(e){console.warn('Quick screening file handoff failed',e);return false}
  }
  async function waitForExtraction(previousText=''){
    const started=Date.now();
    while(Date.now()-started<10000){
      const text=byId('resumeText')?.value?.trim()||'';
      if(text && text!==previousText)return text;
      await sleep(250);
    }
    return byId('resumeText')?.value?.trim()||'';
  }
  async function waitForScreening(beforeCount){
    const started=Date.now();
    while(Date.now()-started<8000){
      try{if((db.screenings||[]).length>beforeCount)return (db.screenings||[]).at(-1)}catch{}
      await sleep(200);
    }
    try{return (db.screenings||[]).at(-1)||null}catch{return null}
  }
  function summaryFor(s,c,r){
    const m=s?.metrics||{};
    const strengths=[]; const risks=[];
    const requiredGaps=m.missingRequired||s?.missing||[];
    if((m.mandatoryPct||0)>=75)strengths.push(`${m.mandatoryPct}% mandatory skill coverage`);
    if((m.expPct||0)>=90)strengths.push('experience meets the role requirement');
    if((m.domainPct||0)>=55)strengths.push('good role/domain overlap');
    if((m.locPct||0)>=80)strengths.push('location alignment');
    if(requiredGaps.length)risks.push(`${requiredGaps.length} mandatory skill${requiredGaps.length===1?'':'s'} not clearly evidenced`);
    if((m.expPct||100)<75)risks.push('experience depth needs verification');
    if((m.locPct||100)<60)risks.push('location/work-mode fit needs confirmation');
    const opening=s?.recommendation==='Strong Match'?'This profile is a strong shortlist candidate.':s?.recommendation==='Review Recommended'?'This profile is worth a recruiter review before submission.':'This profile has meaningful gaps against the selected requirement.';
    return `${opening} The candidate scored ${s?.score??0}/100 for ${r?.title||'the selected role'}. ${strengths.length?`Key strengths: ${strengths.join(', ')}. `:''}${risks.length?`Verify before submission: ${risks.join('; ')}.`:'No major mandatory gap is visible from the available resume evidence.'}`;
  }
  function screeningQuestion(s,r){
    const missing=(s?.metrics?.missingRequired||s?.missing||[])[0];
    if(missing)return `Can you describe your hands-on experience with ${missing}?`;
    const skill=(r?.skills||[])[0];
    return skill?`Can you describe a recent project where you used ${skill}?`:`Can you walk me through your most relevant experience for ${r?.title||'this role'}?`;
  }
  function renderResult(s){
    if(!s)return;
    let c=null,r=null;
    try{c=(db.candidates||[]).find(x=>String(x.id)===String(s.candidateId));r=(db.requirements||[]).find(x=>String(x.id)===String(s.requirementId))}catch{}
    const node=byId('quickResult'); if(!node)return;
    const cls=s.recommendation==='Strong Match'?'strong':s.recommendation==='Review Recommended'?'review':'weak';
    node.classList.remove('hidden');
    node.innerHTML=`
      <div class="quick-result-top">
        <div class="quick-score" style="--q-score:${Math.max(0,Math.min(100,Number(s.score)||0))*3.6}deg"><strong>${esc(s.score)}/100</strong></div>
        <div class="quick-result-copy"><h3>${esc(c?.name||'Candidate')}</h3><p>${esc(r?.title||'Role')} · ${esc(r?.client||'Client')}</p></div>
        <span class="quick-verdict ${cls}">${esc(s.recommendation)}</span>
      </div>
      <div class="quick-ai-summary"><span>QUICK VERDICT</span><p>${esc(summaryFor(s,c,r))}</p></div>
      <div class="quick-result-columns">
        <div class="quick-result-box"><strong>Matching skills</strong><div class="skill-cloud">${(s.matched||[]).map(x=>`<span class="skill">${esc(x)}</span>`).join('')||'<small>No exact match captured</small>'}</div></div>
        <div class="quick-result-box"><strong>Missing / verify</strong><div class="skill-cloud">${(s.missing||[]).map(x=>`<span class="skill ai">${esc(x)}</span>`).join('')||'<small>No major mandatory gaps</small>'}</div></div>
      </div>
      <div class="quick-next-question"><b>Best recruiter question:</b> ${esc(screeningQuestion(s,r))}</div>
      <div class="quick-result-actions">
        <button class="primary" id="quickSaveCandidate">Save Candidate to Todo</button>
        <button class="primary" data-qdecision="Shortlisted">Shortlist</button>
        <button data-qdecision="Keep for Future">Keep for Future</button>
        <button data-qdecision="Request Updated Resume">Request Updated Resume</button>
        <button class="danger" data-qdecision="Rejected">Reject</button>
        <button id="quickScheduleInterview">Schedule Interview</button>
        <button id="quickOpenDetailed">Open Detailed Result</button>
      </div>`;
    const saveButton=byId('quickSaveCandidate');
    if(s.serverId){saveButton.disabled=true;saveButton.textContent='✓ Candidate Saved'}
    saveButton?.addEventListener('click',()=>saveCandidate(s));
    node.querySelectorAll('[data-qdecision]').forEach(btn=>btn.addEventListener('click',()=>applyDecision(btn.dataset.qdecision,s)));
    byId('quickScheduleInterview')?.addEventListener('click',async()=>{if(await ensureSaved(s))byId('scheduleInterview')?.click()});
    byId('quickOpenDetailed')?.addEventListener('click',()=>document.querySelector('.nav-item[data-view="screening"]')?.click());
  }
  async function saveCandidate(s){
    const button=byId('quickSaveCandidate');
    if(s?.serverId){if(button){button.disabled=true;button.textContent='✓ Candidate Saved'}return true}
    if(!window.TSSProduction?.persistLatestScreening){setStatus('Secure save is unavailable. Refresh once and retry.','bad');return false}
    if(button){button.disabled=true;button.textContent='Saving…'}
    setStatus('Saving candidate, CV and screening to Todo…','busy');
    const saved=await window.TSSProduction.persistLatestScreening();
    if(saved){if(button){button.disabled=true;button.textContent='✓ Candidate Saved'}setStatus('Candidate saved — now available in Calling Tracker','ok');return true}
    if(button){button.disabled=false;button.textContent='Retry Save Candidate'}
    setStatus('Save did not finish. Retry here; the candidate details will be reused safely.','bad');
    return false;
  }
  async function ensureSaved(s){
    if(s?.serverId)return true;
    setStatus('Save the candidate before adding a decision or interview.','busy');
    return saveCandidate(s);
  }
  async function applyDecision(decision,s){
    if(!await ensureSaved(s))return;
    const source=document.querySelector(`#screeningResult .decision[data-d="${CSS.escape(decision)}"]`);
    if(source){source.click();setStatus(`Decision saved: ${decision}`,'ok');return}
    try{
      const s=(db.screenings||[]).at(-1); if(!s)return;
      s.recruiterDecision=decision; s.manualOverride=true;
      db.activity=db.activity||[];db.activity.push({date:new Date().toISOString(),title:'Recruiter decision',detail:`${decision} — screening ${s.id}`});
      saveDB();setStatus(`Decision saved: ${decision}`,'ok');
    }catch{setStatus('Could not save decision','bad')}
  }
  async function analyse(){
    const button=byId('quickAnalyseBtn'); if(!button)return;
    const req=selectedRequirement();
    if(!req){setStatus('Select a requirement first','bad');return}
    const pasted=(byId('quickResumeText')?.value||'').trim();
    if(!quickFile&&!pasted){setStatus('Drop a CV or paste resume text','bad');return}
    button.disabled=true;button.textContent='Analysing…';setStatus('Reading candidate profile…','busy');
    syncRequirementToCore();
    const previous=byId('resumeText')?.value||'';
    if(pasted){byId('resumeText').value=pasted}
    let fallbackName='';
    if(quickFile){
      fallbackName=deriveNameFromFilename(quickFile.name);
      await feedFileToCore(quickFile);
      setStatus('Extracting CV details…','busy');
      await waitForExtraction(previous);
      // candidate-enrichment intentionally clears stale identity when a new file is handed off.
      // Apply the filename fallback only AFTER parsing has had a chance to populate the real name.
      if(byId('candidateName')&&!byId('candidateName').value.trim()&&fallbackName)byId('candidateName').value=fallbackName;
    }
    if(pasted && byId('candidateName')&&!byId('candidateName').value.trim()){
      const first=pasted.split(/\r?\n/).map(x=>x.trim()).find(Boolean)||'';
      if(first.length<70&&!/@/.test(first))byId('candidateName').value=first;
    }
    const text=byId('resumeText')?.value?.trim()||'';
    if(!text){button.disabled=false;button.textContent='Analyse Candidate';setStatus('Resume text could not be extracted. Paste the resume text once and try again.','bad');return}
    if(byId('candidateName')&&!byId('candidateName').value.trim()){
      const first=text.split(/\r?\n/).map(x=>x.trim()).find(Boolean)||'';
      if(first&&first.length<70&&!/@/.test(first))byId('candidateName').value=first;
    }
    if(byId('candidateName')&&!byId('candidateName').value.trim()){
      button.disabled=false;button.textContent='Analyse Candidate';
      setStatus('Candidate name could not be identified. Enter the name once, then analyse again.','bad');
      return;
    }
    const before=(()=>{try{return (db.screenings||[]).length}catch{return 0}})();
    setStatus('Matching skills, experience and role fit…','busy');
    byId('screenBtn')?.click();
    const result=await waitForScreening(before);
    button.disabled=false;button.textContent='Analyse Candidate';
    if(!result){setStatus('Screening did not complete. Open Detailed Mode to review the input.','bad');return}
    renderResult(result);setStatus('Screening complete — click Save Candidate to add it to Todo and Calling Tracker','ok');
  }
  function mount(){
    const dash=byId('dashboard'); if(!dash||byId('quickScreenCard'))return false;
    const anchor=dash.querySelector('.dashboard-title-row');
    if(!anchor)return false;
    const card=document.createElement('article');
    card.id='quickScreenCard';card.className='old-panel quick-screen-card';
    card.innerHTML=`
      <div class="quick-screen-hero">
        <div><span class="quick-screen-kicker">⚡ QUICK SCREENING</span><h2>Drop a CV. Get the full answer.</h2><p>No jumping between pages and no compulsory download. Select the role, add the CV, and get the recruiter-ready verdict here.</p></div>
        <span class="quick-screen-mode">1-screen mode</span>
      </div>
      <div class="quick-screen-body">
        <div class="quick-screen-grid">
          <div class="quick-screen-block"><label>1 · Select requirement</label><select id="quickRequirement" class="quick-screen-select"></select><label for="quickResumeFile" class="quick-screen-drop" id="quickDropZone"><div><strong>2 · Drop candidate CV here</strong><small>PDF, DOCX, TXT or image-supported CV</small><small id="quickFileName" class="quick-screen-file-name"></small></div></label><input id="quickResumeFile" class="quick-screen-file" type="file" accept=".pdf,.doc,.docx,.txt,.png,.jpg,.jpeg,.webp" /></div>
          <div class="quick-screen-block paste-block"><span class="quick-paste-label">Or paste resume text</span><textarea id="quickResumeText" class="quick-screen-text" placeholder="Paste the resume here if you don't want to upload a file…"></textarea><div class="quick-shortcuts"><button type="button" data-qprompt="fit">Is this candidate fit?</button><button type="button" data-qprompt="gaps">Show skill gaps</button><button type="button" data-qprompt="questions">What should I ask?</button></div></div>
        </div>
        <div class="quick-screen-actions"><button id="quickAnalyseBtn" class="quick-analyse-btn" type="button">Analyse Candidate</button><button id="quickDetailedBtn" class="quick-detailed-btn" type="button">Detailed Mode</button><span id="quickScreenStatus" class="quick-screen-status">Ready</span></div>
        <div id="quickResult" class="quick-result hidden"></div>
      </div>`;
    anchor.insertAdjacentElement('afterend',card);
    populateQuickRequirements();
    byId('quickAnalyseBtn').addEventListener('click',analyse);
    byId('quickDetailedBtn').addEventListener('click',()=>document.querySelector('.nav-item[data-view="screening"]')?.click());
    byId('quickRequirement').addEventListener('change',syncRequirementToCore);
    const input=byId('quickResumeFile'),drop=byId('quickDropZone');
    input.addEventListener('change',()=>{quickFile=input.files?.[0]||null;byId('quickFileName').textContent=quickFile?quickFile.name:'';setStatus(quickFile?'CV ready to analyse':'Ready',quickFile?'ok':'')});
    ['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('drag')}));
    ['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('drag')}));
    drop.addEventListener('drop',e=>{quickFile=e.dataTransfer?.files?.[0]||null;if(quickFile){byId('quickFileName').textContent=quickFile.name;setStatus('CV ready to analyse','ok')}});
    document.querySelectorAll('[data-qprompt]').forEach(b=>b.addEventListener('click',()=>{if(!byId('quickResult').classList.contains('hidden'))byId('quickResult').scrollIntoView({behavior:'smooth',block:'nearest'});else setStatus('Add a CV and analyse once — the answer will appear here.','busy')}));
    return true;
  }
  function refresh(){populateQuickRequirements()}
  const timer=setInterval(()=>{if(mount()){clearInterval(timer);setTimeout(refresh,800)}},250);
  window.addEventListener('tss:hydrated',refresh);
  window.addEventListener('focus',refresh);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
  window.TSSQuickScreening={refresh,analyse};
})();

/* ===== quick-screening-next.js ===== */
(function(){
  const $=id=>document.getElementById(id);
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  let lastSignature='';
  function latest(){try{return (db.screenings||[]).at(-1)||null}catch{return null}}
  function candidateFor(s){try{return (db.candidates||[]).find(c=>String(c.id)===String(s?.candidateId))||null}catch{return null}}
  function requirementFor(s){try{return (db.requirements||[]).find(r=>String(r.id)===String(s?.requirementId))||null}catch{return null}}
  function details(s){return s?.aiDetails||{}}
  function text(v,fallback='Needs verification'){return String(v||fallback)}
  function riskText(s,d){
    const risks=[...(d.redFlags||[]),...(d.gaps||[])];
    if(!risks.length&&(s?.missing||[]).length)risks.push(`${s.missing.length} mandatory skill(s) are not clearly evidenced.`);
    return risks[0]||'No major red flag detected from the available resume evidence.';
  }
  function brief(s,c,r,d){
    const strengths=(d.strengths||[]).slice(0,2).join(' ');
    const gaps=(d.gaps||[]).slice(0,1).join(' ');
    const opening=`${c?.name||'Candidate'} scored ${s?.score||0}/100 for ${r?.title||'the role'} and is marked ${s?.recommendation||'for review'}.`;
    return [opening,strengths,gaps?`Key verification point: ${gaps}`:''].filter(Boolean).join(' ');
  }
  async function copyText(value,button,label='Copied'){
    try{await navigator.clipboard.writeText(value);const old=button.textContent;button.textContent=label;button.classList.add('quick-copy-ok');setTimeout(()=>{button.textContent=old;button.classList.remove('quick-copy-ok')},1400)}catch{button.textContent='Copy failed'}
  }
  function resetQuick(){
    const file=$('quickResumeFile'),paste=$('quickResumeText'),result=$('quickResult'),name=$('candidateName');
    if(file)file.value='';if(paste)paste.value='';if(result){result.innerHTML='';result.classList.add('hidden')}if(name)name.value='';
    const fn=$('quickFileName');if(fn)fn.textContent='';
    const st=$('quickScreenStatus');if(st){st.textContent='Ready for next candidate';st.className='quick-screen-status ok'}
    $('quickScreenCard')?.scrollIntoView({behavior:'smooth',block:'start'});
  }
  function addEnhancements(){
    const node=$('quickResult'),s=latest();if(!node||node.classList.contains('hidden')||!s)return;
    const sig=`${s.id}-${s.score}-${s.recommendation}`;if(sig===lastSignature&&node.querySelector('.quick-copilot-bar'))return;lastSignature=sig;
    const c=candidateFor(s),r=requirementFor(s),d=details(s);
    const fitValues=[['Experience',text(d.experienceFit,s.metrics?.expPct!=null?`${s.metrics.expPct}% match`:undefined)],['Location',text(d.locationFit,s.metrics?.locPct!=null?`${s.metrics.locPct}% match`:undefined)],['Qualification',text(d.qualificationFit)],['Rating',d.rating?`${d.rating}/5`:s.score>=80?'Strong':s.score>=55?'Review':'Weak']];
    const top=node.querySelector('.quick-ai-summary')||node.querySelector('.quick-result-top');
    if(top&&!node.querySelector('.quick-fit-grid'))top.insertAdjacentHTML('afterend',`<div class="quick-fit-grid">${fitValues.map(([k,v])=>`<div class="quick-fit-card"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`);
    const briefText=brief(s,c,r,d);
    const actions=node.querySelector('.quick-result-actions');
    if(actions&&!node.querySelector('.quick-submission-brief'))actions.insertAdjacentHTML('beforebegin',`<div class="quick-risk-line"><b>Verify before client submission:</b> ${esc(riskText(s,d))}</div><div class="quick-submission-brief"><div class="quick-submission-brief-head"><span>CLIENT-SUBMISSION READY BRIEF</span><button type="button" id="quickCopyBrief">Copy Summary</button></div><p>${esc(briefText)}</p></div><div class="quick-copilot-bar"><b>Recruiter Copilot</b><button type="button" data-copy="questions">Copy Screening Questions</button><button type="button" data-copy="whatsapp">Copy WhatsApp Summary</button><button type="button" data-copy="reason">Why this score?</button></div>`);
    if(actions&&!actions.querySelector('.quick-new-screen'))actions.insertAdjacentHTML('beforeend','<button type="button" class="quick-new-screen">＋ New Screening</button>');
    const copyBrief=$('quickCopyBrief');if(copyBrief)copyBrief.onclick=()=>copyText(briefText,copyBrief,'Copied ✓');
    node.querySelectorAll('[data-copy]').forEach(btn=>btn.onclick=()=>{
      const type=btn.dataset.copy;
      const questions=(d.recruiterQuestions||[]).length?(d.recruiterQuestions||[]).map((q,i)=>`${i+1}. ${q}`).join('\n'):`1. ${s.missing?.[0]?`Please explain your hands-on experience with ${s.missing[0]}.`:`Walk me through your most relevant experience for ${r?.title||'this role'}.`}`;
      const value=type==='questions'?questions:type==='whatsapp'?`${c?.name||'Candidate'} | ${r?.title||'Role'} | Match: ${s.score}/100 | ${s.recommendation}. ${d.summary||briefText}`:`Score ${s.score}/100. ${d.decisionReason||d.summary||briefText}`;
      copyText(value,btn,'Copied ✓');
    });
    node.querySelector('.quick-new-screen')?.addEventListener('click',resetQuick);
  }
  function mountTip(){const body=$('quickScreenCard')?.querySelector('.quick-screen-body');if(body&&!body.querySelector('.quick-screen-tip'))body.insertAdjacentHTML('beforeend','<div class="quick-screen-tip">Tip: press <kbd>Ctrl</kbd> + <kbd>Enter</kbd> to analyse instantly.</div>')}
  const observer=new MutationObserver(()=>{addEnhancements();mountTip()});
  const timer=setInterval(()=>{const card=$('quickScreenCard'),result=$('quickResult');if(card&&result){clearInterval(timer);observer.observe(result,{childList:true,subtree:true});mountTip();addEnhancements()}},250);
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&!$('quickAnalyseBtn')?.disabled){e.preventDefault();$('quickAnalyseBtn')?.click()}});
  window.TSSQuickScreeningNext={refresh:addEnhancements,reset:resetQuick};
})();

/* ===== todo-chatbot-upgrade.js ===== */
// Broad, deterministic TODO AI recruiter copilot for common TSS questions, navigation and safe recruiter actions.
(function(){
  'use strict';
  const $=s=>document.querySelector(s), E=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const N=v=>String(v??'').toLowerCase().replace(/[^a-z0-9+#. ]/g,' ').replace(/\s+/g,' ').trim();
  const data=()=>{try{return typeof db!=='undefined'?db:null}catch{return null}};
  const reqs=()=>data()?.requirements||[], cands=()=>data()?.candidates||[], screens=()=>data()?.screenings||[], ints=()=>data()?.interviews||[];
  let mode='help';

  function resultBox(){let out=$('.todo-help .todo-ai-results');if(!out){out=document.createElement('div');out.className='todo-ai-results';$('.todo-help')?.appendChild(out)}return out}
  function say(html){const out=resultBox();if(out)out.innerHTML=`<div class="todo-ai-msg">${html}</div>`}
  function openView(v){document.querySelector(`.nav-item[data-view="${v}"]`)?.click()}
  function currentReq(){const id=$('#screenRequirement')?.value||$('#topRequirementSelect')?.value;return reqs().find(r=>String(r.id)===String(id))||reqs().find(r=>/work in progress|active/i.test(r.status||''))||reqs()[0]}
  function byReq(q){const n=N(q);return reqs().find(r=>n.includes(N(r.id))||n.includes(N(r.requirementId)))||reqs().find(r=>n.includes(N(r.title))&&N(r.title).length>3)||reqs().find(r=>n.includes(N(r.client))&&N(r.client).length>3)||currentReq()}
  function byCand(q){const n=N(q);return cands().find(c=>n.includes(N(c.name))&&N(c.name).length>2)||cands().find(c=>c.email&&n.includes(N(c.email)))||cands().find(c=>n.includes(N(c.id)))}
  function counts(){const r=reqs(),s=screens(),i=ints();const w=r.filter(x=>/work in progress|active/i.test(x.status||'')).length,h=r.filter(x=>/on hold/i.test(x.status||'')).length,f=r.filter(x=>/fulfilled/i.test(x.status||'')).length;return {r:r.length,w,h,f,c:cands().length,s:s.length,i:i.length,review:s.filter(x=>x.recommendation==='Review Recommended').length,strong:s.filter(x=>x.recommendation==='Strong Match').length}}
  function guide(topic){const guides={screen:'Go to Screening, select the exact requirement, upload the candidate CV, verify extracted details, then run Screen & Rank. The result shows match score, evidence, gaps and recruiter actions.',candidate:'Candidate Records stores saved candidate profiles and CV history. You can search by name, email, phone, location, designation or skill.',duplicate:'A duplicate alert is triggered when the same candidate is already stored, typically by email or phone, so you do not create duplicate profiles.',interview:'Open Interviews → Schedule Interview. Select the saved candidate and exact requirement/position, then date, time, mode and interview details. Confirmation and reminder emails are queued automatically.',requirement:'Requirements is the master place to add or edit client requirements, JD, owner, handler, recruiters, positions and status.',owner:'Client Owner is mapped client-wise. Once an owner is saved for a client, the same owner is automatically applied to that client’s requirements.',assignment:'When a recruiter is assigned to a requirement, the recruiter receives an assignment email. New assignments are tracked separately and acknowledgement can be recorded.',ack:'The recruiter clicks Acknowledge Assignment in the assignment email. TODO AI then shows whether the assignment is Pending acknowledgement or Acknowledged.',email:'Interview confirmations, reminders and requirement assignment alerts are sent through Microsoft Graph from the configured TSS mailbox. Sent/failed events are tracked by the backend.',reminder:'Interview reminders are queued for 10:00 AM on interview day, 1 hour before, 30 minutes before and 5 minutes before. Reschedule or cancellation updates the reminder flow.',score:'The screening score compares the candidate against the selected requirement using mandatory/preferred skills, experience, title relevance, responsibilities/domain evidence and location. Always review evidence, not just the number.',reschedule:'If a candidate requests reschedule from the email, TODO AI records Reschedule Requested and the candidate’s preferred date/time. The recruiter can then confirm a revised slot.',pipeline:'Pipeline stages help track candidate progress such as shortlisted, interview, final select and joined. Use recruiter actions on the candidate/screening record to update stage.',ctc:'Current CTC, Expected CTC, Notice Period, Current Location, interview availability and relevant experience are common screening questions for every candidate.',report:'Use Master Excel / exports for consolidated recruitment data and screening records. Candidate and requirement data remain linked to their exact records.'};return guides[topic]}

  function selectRequirement(raw){
    const r=byReq(raw);if(!r)return false;
    const id=String(r.id||r.requirementId||'');
    const screen=$('#screenRequirement'),top=$('#topRequirementSelect');
    if(screen&&[...screen.options].some(o=>String(o.value)===id)){screen.value=id;screen.dispatchEvent(new Event('change',{bubbles:true}))}
    if(top&&[...top.options].some(o=>String(o.value)===id)){top.value=id;top.dispatchEvent(new Event('change',{bubbles:true}))}
    openView('screening');
    return r;
  }

  function safeAction(raw){
    const q=N(raw);if(!q)return say('<b>Type an action.</b><br>Example: “Open Interviews” or “Select TSS055 for screening”.');
    if(/open .*screen|go to .*screen|start .*screen/.test(q)){openView('screening');return say('✅ Opened <b>Screening</b>.')}
    if(/open .*candidate|go to .*candidate/.test(q)){openView('candidates');return say('✅ Opened <b>Candidate Records</b>.')}
    if(/open .*interview|go to .*interview/.test(q)){openView('interviews');return say('✅ Opened <b>Interviews</b>.')}
    if(/open .*requirement|go to .*requirement|open .*job profile/.test(q)){openView('requirements');return say('✅ Opened <b>Requirements</b>.')}
    if(/select .*tss|screen .*tss|requirement .*tss|select .*requirement/.test(q)){
      const r=selectRequirement(raw);if(!r)return say('I could not find that requirement. Use the exact TSS ID, client or role.');
      return say(`✅ Selected <b>${E(r.requirementId||r.id)} · ${E(r.client)} — ${E(r.title)}</b> and opened Screening.`)
    }
    if(/schedule .*interview|new interview/.test(q)){
      openView('interviews');setTimeout(()=>$('#scheduleInterview')?.click(),120);
      return say('✅ Opened <b>Schedule Interview</b>. Review candidate, requirement, date and time before saving.')
    }
    if(/final select|joined|rejected|hold|submit.*client|shortlist|pipeline/.test(q)){
      const c=byCand(raw);
      const who=c?` for <b>${E(c.name)}</b>`:'';
      return say(`⚠️ This changes recruitment data${who}. TODO AI will not silently modify a candidate record. Open the candidate/interview record, choose the exact stage and confirm the update there.`)
    }
    return say('<b>Safe Commands can perform navigation and setup actions.</b><br>Try: “Open Screening”, “Select TSS055 for screening”, “Open Interviews”, or “Schedule interview”. Data-changing pipeline actions still require an explicit confirmation in the relevant record.');
  }

  function answer(raw){const q=N(raw);if(!q)return;if(mode==='safe')return safeAction(raw);
    if(/^(hi|hello|hey|hii|hiii|good morning|good afternoon|good evening|namaste)\b/.test(q))return say('<b>Hi! I’m Todo AI.</b><br>Ask me about candidates, requirements, screening, interviews, email alerts, recruiter assignments, acknowledgements, client owners, pipeline or reports.');
    if(/what can you do|help|commands|how can you help/.test(q))return say('<b>I can help with:</b><ul><li>Requirements & JD workflow</li><li>Candidate search and screening</li><li>Scores, gaps and duplicate alerts</li><li>Interview scheduling, confirmation and reschedule flow</li><li>Email reminders and assignment alerts</li><li>Client owner / recruiter assignment / acknowledgement</li><li>Pipeline and recruitment summary</li><li>Opening the correct TODO AI section</li></ul><small>Try: “How do I schedule interview?”, “Show requirement TSS055”, “How many candidates?”, “What is acknowledgement?”</small>');
    const c=counts();
    if(/recruitment summary|dashboard summary|today summary|give.*summary/.test(q))return say(`<b>Recruitment summary</b><ul><li>${c.r} requirements total</li><li>${c.w} work in progress · ${c.h} on hold · ${c.f} fulfilled</li><li>${c.c} saved candidates</li><li>${c.s} screenings · ${c.strong} strong matches · ${c.review} need review</li><li>${c.i} interviews saved</li></ul>`);
    if(/how many.*candidate|candidate count|number of candidates/.test(q))return say(`<b>${c.c}</b> saved candidates are currently available in TODO AI.`);
    if(/how many.*requirement|requirement count|number of requirements/.test(q))return say(`<b>${c.r}</b> requirements total: ${c.w} work in progress, ${c.h} on hold and ${c.f} fulfilled.`);
    if(/how many.*interview|interview count/.test(q))return say(`<b>${c.i}</b> interviews are currently saved.`);
    if(/open .*screen|go to .*screen/.test(q)){openView('screening');return say('Opened <b>Screening</b>.')}
    if(/open .*candidate|go to .*candidate/.test(q)){openView('candidates');return say('Opened <b>Candidate Records</b>.')}
    if(/open .*interview|go to .*interview/.test(q)){openView('interviews');return say('Opened <b>Interviews</b>.')}
    if(/open .*requirement|go to .*requirement|open .*job profile/.test(q)){openView('requirements');return say('Opened <b>Requirements</b>.')}
    if(/show.*requirement|jd for|requirement details|job profile/.test(q)){const r=byReq(q);if(!r)return say('I could not find that requirement. Try the TSS ID, client name or role.');return say(`<b>${E(r.requirementId||r.id)} · ${E(r.client)} — ${E(r.title)}</b><ul><li>Status: ${E(r.status||'Not set')}</li><li>Location: ${E(r.location||'Not provided')}</li><li>Experience: ${E(r.experience||'Not provided')}</li><li>Owner: ${E(r.clientOwner||'Not assigned')}</li><li>Mandatory skills: ${E((r.skills||[]).join(', ')||'Not confirmed')}</li><li>Preferred skills: ${E((r.preferred||[]).join(', ')||'Not confirmed')}</li></ul>`)}
    if(/show.*candidate|candidate details|find candidate/.test(q)){const x=byCand(q);if(x)return say(`<b>${E(x.name)}</b><ul><li>Email: ${E(x.email||'—')}</li><li>Phone: ${E(x.phone||'—')}</li><li>Location: ${E(x.location||'—')}</li><li>Designation: ${E(x.designation||'—')}</li><li>Experience: ${E(x.totalExperience||'—')}</li></ul>`);return say('Mention the candidate name, email or candidate ID and I’ll look in saved Candidate Records.')}
    if(/duplicate/.test(q))return say(guide('duplicate'));
    if(/acknowledge|acknowledgement|acknowledgment/.test(q))return say(guide('ack'));
    if(/assign.*recruiter|recruiter assignment|assigned recruiter/.test(q))return say(guide('assignment'));
    if(/client owner|account owner|owner mapping/.test(q))return say(guide('owner'));
    if(/reschedule/.test(q))return say(guide('reschedule'));
    if(/reminder/.test(q))return say(guide('reminder'));
    if(/email|mail alert|mail notification/.test(q))return say(guide('email'));
    if(/schedule.*interview|how.*interview|interview process/.test(q))return say(guide('interview'));
    if(/screen.*cv|screen.*resume|how.*screen|screening process/.test(q))return say(guide('screen'));
    if(/score|match score|why.*low|why.*high/.test(q))return say(guide('score'));
    if(/requirement|jd/.test(q))return say(guide('requirement'));
    if(/pipeline|stage|final select|joined/.test(q))return say(guide('pipeline'));
    if(/current ctc|expected ctc|notice period|availability question|screening question/.test(q))return say(guide('ctc'));
    if(/report|excel|export/.test(q))return say(guide('report'));
    if(/candidate/.test(q))return say(guide('candidate'));
    return say(`<b>I can help with that inside the recruitment workflow.</b><br>For the clearest result, include the candidate name, TSS requirement ID, client, role or action you want.<small>Examples: “Show TSS055”, “How do I reschedule an interview?”, “What is recruiter acknowledgement?”, “How many candidates?”, “Open interviews”.</small>`);
  }

  function setMode(next){
    mode=next;
    const help=$('.todo-help');if(!help)return;
    const tabs=[...help.querySelectorAll('.todo-tabs button')];
    tabs.forEach((b,i)=>b.classList.toggle('active',(next==='help'&&i===0)||(next==='safe'&&i===1)));
    const p=help.querySelector(':scope > p');
    const input=help.querySelector('.todo-command input');
    const chips=help.querySelector('.chips');
    const small=help.querySelector(':scope > small');
    if(next==='safe'){
      if(p)p.textContent='Run controlled recruiter actions. Navigation happens immediately; data-changing actions require confirmation.';
      if(input)input.placeholder='Try: Select TSS055 for screening';
      if(chips)chips.innerHTML='<button>Open Screening</button><button>Open Requirements</button><button>Schedule interview</button><button>Open Candidates</button>';
      if(small)small.textContent='Safe Commands never silently change candidate or requirement data.';
      say('<b>Safe Commands is active.</b><br>Try an action such as “Open Screening” or “Select TSS055 for screening”.');
    }else{
      if(p)p.textContent='Ask me to find candidates, explain scores, open profiles, schedule interviews, or understand TSS workflows.';
      if(input)input.placeholder='How do I screen a CV?';
      if(chips)chips.innerHTML='<button>How do I screen a CV?</button><button>What is a duplicate alert?</button><button>How do I submit a candidate to a client?</button><button>How do I schedule an interview?</button>';
      if(small)small.textContent='Help mode explains and guides. Use Safe Commands for controlled actions.';
      say('<b>Todo AI help is active.</b><br>Ask a recruitment question or use one of the quick prompts.');
    }
    wireChips();
  }

  function wireChips(){
    const input=$('.todo-command input');if(!input)return;
    document.querySelectorAll('.todo-help .chips button').forEach(b=>{b.onclick=e=>{e.preventDefault();e.stopPropagation();input.value=b.textContent||'';answer(input.value)}})
  }
  function wire(){
    const input=$('.todo-command input'),btn=$('.todo-command button');if(!input||!btn)return;
    btn.onclick=e=>{e.preventDefault();e.stopPropagation();answer(input.value)};
    input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();answer(input.value)}};
    const tabs=[...document.querySelectorAll('.todo-help .todo-tabs button')];
    if(tabs[0]){tabs[0].textContent='Todo AI';tabs[0].onclick=e=>{e.preventDefault();setMode('help')}}
    if(tabs[1]){tabs[1].textContent='Safe Commands';tabs[1].onclick=e=>{e.preventDefault();setMode('safe')}}
    wireChips();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(wire,250),{once:true});else setTimeout(wire,250);
  window.addEventListener('load',()=>setTimeout(wire,600),{once:true});
  window.TSSTodoChatbot={answer,wire,setMode,safeAction};
})();

/* ===== role-access-visibility.js ===== */
// Role-based visibility: shared candidate database, recruiter-owned interviews, admin oversight.
(function(){
  'use strict';
  const backend=()=>window.TSSBackend;
  const DB=()=>{try{return typeof db!=='undefined'?db:null}catch{return null}};
  let role='recruiter', userId='', interviewMeta=new Map(), profileMap=new Map();
  function recruiterLabel(profile){
    const raw=String(profile?.full_name||profile?.email||'Recruiter').split('@')[0].trim();
    return raw.replace(/[._-]+/g,' ').replace(/\b\w/g,char=>char.toUpperCase())||'Recruiter';
  }

  async function getRole(){
    const b=backend(); if(!b?.enabled)return {role:'recruiter',user:null};
    const user=await b.currentUser().catch(()=>null); if(!user)return {role:'recruiter',user:null};
    userId=user.id;
    const {data}=await b.client.from('profiles').select('id,full_name,email,role').eq('id',user.id).maybeSingle();
    role=String(data?.role||'recruiter').toLowerCase();
    return {role,user,profile:data};
  }

  async function refreshInterviewScope(){
    const b=backend(),store=DB(); if(!b?.enabled||!store)return;
    const {data:rows,error}=await b.client.from('interviews').select('id,created_by,status,candidate_response,reschedule_preferred_date,reschedule_preferred_time').order('scheduled_at',{ascending:true});
    if(error)throw error;
    interviewMeta=new Map((rows||[]).map(x=>[String(x.id),x]));

    // RLS is authoritative: recruiter query returns only their interviews; admin query returns all.
    const allowed=new Set((rows||[]).map(x=>String(x.id)));
    store.interviews=(store.interviews||[]).filter(i=>allowed.has(String(i.serverId||i.id)));
    profileMap=new Map();
    if(role==='admin'){
      const {data:profiles}=await b.client.from('profiles').select('id,full_name,email');
      profileMap=new Map((profiles||[]).map(p=>[String(p.id),p]));
    }else{
      const {data:self}=await b.client.from('profiles').select('id,full_name,email').eq('id',userId).maybeSingle();
      if(self)profileMap.set(String(self.id),self);
    }
    store.interviews.forEach(item=>{
      const meta=interviewMeta.get(String(item.serverId||item.id));
      if(!meta)return;
      const profile=profileMap.get(String(meta.created_by));
      item.createdBy=meta.created_by||null;
      item.scheduledBy=recruiterLabel(profile);
    });
    try{localStorage.setItem('tss_talent_buddy_v1',JSON.stringify(store))}catch{}
    try{window.renderOldSite?.()}catch{}
    setTimeout(()=>window.TSSInterviewActions?.renderStable?.(true),60);
  }

  function ensureScopeNote(){
    const board=document.getElementById('interviewBoard'); if(!board)return;
    let note=document.getElementById('interviewScopeNote');
    if(!note){note=document.createElement('div');note.id='interviewScopeNote';note.className='role-scope-note';board.before(note);}
    note.innerHTML=role==='admin'
      ? '<b>Admin view:</b> All recruiters\' interviews and candidate responses are visible here.'
      : '<b>My interviews:</b> Only interviews scheduled by you are shown here.';
  }

  function ensureCandidateNote(){
    const view=document.getElementById('candidates'); if(!view)return;
    let note=document.getElementById('candidateSharedNote');
    if(!note){note=document.createElement('div');note.id='candidateSharedNote';note.className='role-scope-note shared';const first=view.querySelector('.section-head,.section-title,.card');if(first)first.after(note);else view.prepend(note);}
    note.innerHTML='<b>Shared Candidate Database:</b> All authenticated TSS recruiters can view the common candidate database. Editing/deleting remains restricted to the record owner or Admin.';
  }

  function decorateInterviewBoard(){
    ensureScopeNote(); ensureCandidateNote();
  }

  function style(){if(document.getElementById('roleAccessStyle'))return;const s=document.createElement('style');s.id='roleAccessStyle';s.textContent=`.role-scope-note{margin:0 0 12px;padding:10px 13px;border:1px solid #234d6d;border-radius:10px;background:#0a2133;color:#a9c7dc;font-size:12px}.role-scope-note b{color:#e8f5ff}.role-scope-note.shared{border-color:#285f70;background:#0a252d}`;document.head.appendChild(s)}

  async function boot(){
    style();
    const ctx=await getRole(); if(!ctx.user)return;
    await refreshInterviewScope();
    ensureCandidateNote();
    window.addEventListener('focus',()=>setTimeout(()=>refreshInterviewScope().catch(()=>{}),80));
  }

  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>boot().catch(console.warn),300),{once:true});else setTimeout(()=>boot().catch(console.warn),300);
  window.TSSRoleAccessVisibility={boot,refreshInterviewScope,decorateInterviewBoard,recruiterLabel,get role(){return role}};
})();

/* ===== realtime-performance.js ===== */
// One authoritative realtime coordinator for TODO AI.
(function(){
  'use strict';
  if(window.__TSS_REALTIME_PERFORMANCE__)return;
  window.__TSS_REALTIME_PERFORMANCE__=true;
  const backend=()=>window.TSSBackend;
  let channel=null,refreshTimer=null,reconnectTimer=null,stateTimer=null,subscribePromise=null;
  let refreshing=false,refreshAgain=false,lastRefresh=0,reconnectAttempt=0,booted=false,channelReady=false,pausedUntil=0;
  let online=navigator.onLine;

  function paintState(state){
    document.documentElement.dataset.tssLive=state;
    const indicator=document.querySelector('#backendIndicator');
    if(indicator)indicator.className='backend-indicator '+(state==='on'?'':'off');
    const label=document.querySelector('#backendIndicator span');
    if(label)label.textContent=state==='on'?'Live updates on':state==='offline'?'Offline · changes saved locally':'Reconnecting…';
  }
  function setState(state){
    clearTimeout(stateTimer);stateTimer=null;
    if(state==='on'||state==='offline'){paintState(state);return}
    // Brief reconnects are normal during auth refreshes and tab wake-up.
    stateTimer=setTimeout(()=>{if(!channelReady&&online)paintState('degraded')},1500);
  }
  function setSyncing(active){
    if(active)document.documentElement.dataset.tssSyncing='true';else delete document.documentElement.dataset.tssSyncing;
    const indicator=document.querySelector('#backendIndicator');
    if(indicator)indicator.setAttribute('aria-busy',active?'true':'false');
  }
  function renderOnce(){
    try{if(typeof renderAll==='function')renderAll()}catch(e){console.warn('TODO AI render',e)}
    try{if(typeof renderOldSite==='function')renderOldSite()}catch(e){console.warn('TODO AI legacy render',e)}
    document.dispatchEvent(new CustomEvent('tss:data-rendered'));
  }
  function installSave(){
    if(typeof window.saveDB!=='function'||window.saveDB.__tssCoordinated)return;
    const original=window.saveDB;
    const coordinated=function(){const result=original.apply(this,arguments);queueMicrotask(renderOnce);return result};
    coordinated.__tssCoordinated=true;window.saveDB=coordinated;
  }
  async function refresh(reason='background',force=false){
    if(!online||document.visibilityState==='hidden')return false;
    if(Date.now()<pausedUntil){refreshAgain=true;return false}
    if(refreshing){refreshAgain=true;return false}
    if(!force&&Date.now()-lastRefresh<5000)return false;
    refreshing=true;setSyncing(true);
    try{
      await window.TSSProduction?.hydrate?.();
      lastRefresh=Date.now();if(channelReady)setState('on');
      console.info('TODO AI sync complete',reason);return true;
    }catch(e){setState('degraded');console.warn('TODO AI sync failed',reason,e?.message||e);return false}
    finally{refreshing=false;setSyncing(false);if(refreshAgain){refreshAgain=false;scheduleRefresh('queued',250,true)}}
  }
  function scheduleRefresh(reason='change',delay=180,force=false){
    clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh(reason,force),delay);
  }
  function pause(ms=15000){pausedUntil=Math.max(pausedUntil,Date.now()+ms);clearTimeout(refreshTimer);refreshTimer=null}
  function resume(){pausedUntil=0;if(refreshAgain){refreshAgain=false;scheduleRefresh('save-complete',500,true)}}
  function scheduleReconnect(){
    if(!online||reconnectTimer)return;
    const delay=Math.min(30000,1000*(2**Math.min(reconnectAttempt++,5)));
    reconnectTimer=setTimeout(()=>{reconnectTimer=null;subscribe()},delay);
  }
  async function removeChannel(){
    if(!channel)return;const current=channel;channel=null;channelReady=false;
    try{await backend()?.client?.removeChannel(current)}catch{}
  }
  async function subscribeOnce(){
    const b=backend();if(!b?.enabled||!b.client||!online)return false;
    const {data:{session}}=await b.client.auth.getSession();if(!session?.user)return false;
    await removeChannel();
    const next=b.client.channel('tss-operational-live-v3');channel=next;channelReady=false;
    ['requirements','candidates','screenings','interviews'].forEach(table=>next.on('postgres_changes',{event:'*',schema:'public',table},()=>scheduleRefresh(table,250,true)));
    next.subscribe((status,error)=>{
      if(channel!==next)return;
      if(status==='SUBSCRIBED'){
        channelReady=true;reconnectAttempt=0;clearTimeout(reconnectTimer);reconnectTimer=null;
        setState('on');scheduleRefresh('reconnected',250,true);
      }else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED'){
        channelReady=false;console.warn('TODO AI realtime connection',status,error||'');setState('degraded');scheduleReconnect();
      }
    });
    return true;
  }
  function subscribe(){
    if(subscribePromise)return subscribePromise;
    subscribePromise=subscribeOnce().finally(()=>{subscribePromise=null});
    return subscribePromise;
  }
  function installLifecycle(){
    window.addEventListener('online',()=>{online=true;subscribe()},{passive:true});
    window.addEventListener('offline',()=>{online=false;setState('offline');removeChannel()},{passive:true});
    window.addEventListener('focus',()=>scheduleRefresh('focus',150,false),{passive:true});
    document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')scheduleRefresh('visible',150,false)});
    document.addEventListener('tss:data-changed',()=>scheduleRefresh('local-change',250,true));
    window.addEventListener('pagehide',()=>removeChannel(),{once:true});
  }
  function installAuth(){
    backend()?.client?.auth?.onAuthStateChange?.((event,session)=>{
      if(session?.user&&(event==='SIGNED_IN'||event==='INITIAL_SESSION'))setTimeout(()=>{subscribe();scheduleRefresh(event,100,true)},0);
      if(event==='SIGNED_OUT'){removeChannel();setState('offline')}
    });
  }
  async function boot(){
    if(booted)return;booted=true;installSave();installLifecycle();installAuth();
    const connected=await subscribe();
    if(connected)await refresh('startup',true);else setState(online?'degraded':'offline');
    setInterval(()=>{if(document.visibilityState==='visible')scheduleRefresh('fallback',0,false)},120000);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(boot,50),{once:true});else setTimeout(boot,50);
  window.TSSRealtimePerformance={boot,subscribe,refresh,backgroundRefresh:refresh,scheduleRefresh,removeChannel,pause,resume};
})();

/* ===== workflow-finalization.js ===== */
(function(){
'use strict';
if(window.__TSS_WORKFLOW_FINALIZATION__)return;window.__TSS_WORKFLOW_FINALIZATION__=true;
const backend=()=>window.TSSBackend;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const toast=m=>{try{window.toast?.(m)}catch{console.log(m)}};

function normalizeNav(){
  const nav=$('#nav');if(!nav)return;
  const admins=[...nav.querySelectorAll('.nav-item')].filter(x=>['admin','adminView'].includes(x.dataset.view));
  const primary=admins.find(x=>x.dataset.view==='admin')||admins.find(x=>x.id==='adminNavBtn')||admins[0];
  admins.filter(x=>x!==primary).forEach(x=>x.remove());
  const reports=$('#reportsNav');if(reports)reports.innerHTML='<span>▤</span>Reports';
  const admin=primary;
  if(reports&&admin&&reports.nextElementSibling!==admin)nav.insertBefore(reports,admin);
}

function simplifyReports(){
  const root=$('#reportsRoot');if(!root)return;
  const heading=root.querySelector('.section-head h1');if(heading)heading.textContent='Management Reports';
  const sub=root.querySelector('.section-head p');if(sub)sub.textContent='Team performance, requirement progress and daily candidate submissions in one place.';
  const tabs=root.querySelector('.report-tabs');
  if(tabs){
    const perf=tabs.querySelector('[data-tab="performance"]');if(perf)perf.textContent='Team Performance';
    tabs.querySelector('[data-tab="team"]')?.remove();
    tabs.querySelector('[data-tab="audit"]')?.remove();
  }
  [...root.querySelectorAll('.report-panel')].forEach(p=>{
    const h=p.querySelector('h3');if(h&&/management snapshot/i.test(h.textContent||''))p.remove();
  });
}
function applyReportCleanup(){simplifyReports();normalizeNav();setTimeout(simplifyReports,80);setTimeout(simplifyReports,250);setTimeout(simplifyReports,700)}

const STAGES=['Scheduled','Interview Completed','Client Feedback Pending','Result Received','Joining / Closure'];
const RESULTS=['Pending','Second Round','Selected','Hold','Rejected','Client Rejected','Candidate Declined','Candidate Not Available','No Show','Reschedule','Offer / Joining Formalities','Joined-TSS'];

function outcomeDialog(){
  let d=$('#tssOutcomeDialog');if(d)return d;
  d=document.createElement('dialog');d.id='tssOutcomeDialog';
  d.innerHTML=`<form method="dialog" class="tss-outcome-form"><div class="dialog-head"><div><span class="purple-label">INTERVIEW PROGRESS</span><h3>Update Interview</h3><p style="margin:4px 0 0;color:#68788a;font-size:12px">Track the interview through 5 clear stages. Every saved update is emailed to active Admins and Super Admins.</p></div><button value="cancel" class="icon-btn">×</button></div><label>Interview Stage</label><select id="tssStageSelect">${STAGES.map(x=>`<option>${x}</option>`).join('')}</select><label>Interview Result</label><select id="tssOutcomeSelect">${RESULTS.map(x=>`<option>${x}</option>`).join('')}</select><label>Feedback / Notes</label><textarea id="tssOutcomeNotes" rows="4" placeholder="Client feedback, next round, joining update, reason for rejection, etc."></textarea><div style="font-size:11px;color:#68788a;margin-top:8px">Flow: Scheduled → Completed → Feedback Pending → Result Received → Joining / Closure</div><div class="dialog-actions"><button value="cancel" class="btn ghost">Cancel</button><button type="button" id="tssSaveOutcome" class="btn primary">Save Interview Update</button></div></form>`;
  document.body.appendChild(d);return d;
}

async function updateOutcome(id){
  const c=backend()?.client;if(!c)return toast('Backend not available');
  const {data:iv,error}=await c.from('interviews').select('id,candidate_id,requirement_id,interview_stage,outcome,outcome_notes').eq('id',id).maybeSingle();
  if(error||!iv)return toast('Interview record not found');
  const d=outcomeDialog();d.dataset.id=id;
  $('#tssStageSelect').value=STAGES.includes(iv.interview_stage)?iv.interview_stage:'Scheduled';
  $('#tssOutcomeSelect').value=RESULTS.includes(iv.outcome)?iv.outcome:'Pending';
  $('#tssOutcomeNotes').value=iv.outcome_notes||'';d.showModal();
}

function pipelineFor(outcome){
  if(outcome==='Selected'||outcome==='Offer / Joining Formalities')return 'Final Select';
  if(outcome==='Joined-TSS')return 'Joined-TSS';
  if(['Rejected','Client Rejected','Candidate Declined','No Show'].includes(outcome))return 'Rejected';
  return 'Interview';
}
function statusFor(stage,outcome){
  if(outcome==='No Show')return 'No Show';
  if(outcome==='Reschedule')return 'Scheduled';
  if(outcome==='Hold')return 'On Hold';
  if(['Selected','Rejected','Client Rejected','Candidate Declined','Joined-TSS','Offer / Joining Formalities'].includes(outcome))return 'Completed';
  if(stage==='Client Feedback Pending')return 'Feedback Pending';
  if(stage==='Interview Completed'||stage==='Result Received'||stage==='Joining / Closure')return 'Completed';
  return 'Scheduled';
}

async function saveOutcome(){
  const d=$('#tssOutcomeDialog'),id=d?.dataset.id,c=backend()?.client;if(!id||!c)return;
  const stage=$('#tssStageSelect').value,outcome=$('#tssOutcomeSelect').value,notes=$('#tssOutcomeNotes').value.trim(),now=new Date().toISOString();
  try{
    const {data:iv,error}=await c.from('interviews').update({interview_stage:stage,outcome,outcome_notes:notes,outcome_updated_at:now,status:statusFor(stage,outcome)}).eq('id',id).select('candidate_id,requirement_id').single();
    if(error)throw error;
    const pipeline=pipelineFor(outcome);
    if(iv?.candidate_id&&iv?.requirement_id){
      const {data:s}=await c.from('screenings').select('id').eq('candidate_id',iv.candidate_id).eq('requirement_id',iv.requirement_id).order('screened_at',{ascending:false}).limit(1).maybeSingle();
      if(s?.id)await c.from('screenings').update({recruiter_decision:pipeline}).eq('id',s.id);
    }
    try{
      const user=await backend().currentUser?.();
      if(user)await c.from('activity_logs').insert({actor_id:user.id,action:'Interview stage/result updated',entity_type:'interviews',entity_id:id,details:{stage,outcome,pipeline,management_email_queued:true}});
    }catch{}
    d.close();toast(`Interview updated: ${stage} · ${outcome}`);
    await window.TSSProduction?.hydrate?.();
    setTimeout(()=>window.TSSInterviewActions?.syncStatuses?.(),80);
    setTimeout(decorateInterviewOutcomes,180);
  }catch(e){console.error(e);toast('Could not save interview update: '+(e.message||e))}
}

function decorateInterviewOutcomes(){
  const board=$('#interviewBoard');if(!board)return;
  const rows=[...board.querySelectorAll('tbody tr')];
  rows.forEach((tr,idx)=>{
    const cell=tr.querySelector('[data-ia-actions]');if(!cell||cell.querySelector('.ia-outcome'))return;
    const local=(typeof db!=='undefined'?(db.interviews||[])[idx]:null);
    const id=String(local?.serverId||local?.id||'');if(!id)return;
    const b=document.createElement('button');b.type='button';b.className='ia-btn ia-outcome';b.dataset.iaOutcome=id;b.textContent='Update Interview';cell.prepend(b);
  });
}

function pulse(){normalizeNav();if($('#reportsActivity')?.classList.contains('active'))simplifyReports();if($('#interviews')?.classList.contains('active'))decorateInterviewOutcomes()}
function wire(){
  normalizeNav();
  document.addEventListener('click',e=>{
    const out=e.target.closest('[data-ia-outcome]');if(out){updateOutcome(out.dataset.iaOutcome);return}
    if(e.target.id==='tssSaveOutcome'){saveOutcome();return}
    if(e.target.closest('#reportsNav'))setTimeout(applyReportCleanup,100);
    if(e.target.closest('.nav-item[data-view="interviews"]'))setTimeout(decorateInterviewOutcomes,140);
  });
  setTimeout(()=>{decorateInterviewOutcomes();applyReportCleanup();normalizeNav()},450);
  document.addEventListener('tss:data-rendered',pulse);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',wire,{once:true});else wire();
window.TSSWorkflowFinalization={simplifyReports,cleanDuplicateAdmin:normalizeNav,decorateInterviewOutcomes,updateOutcome};
})();

/* ===== requirement-screening-selection-fix.js ===== */
// Keep the exact requirement selected when "Screen Candidate" is launched from Requirements.
(function(){
  'use strict';
  if(window.__TSS_REQUIREMENT_SCREENING_SELECTION_FIX__) return;
  window.__TSS_REQUIREMENT_SCREENING_SELECTION_FIX__ = true;

  const $ = id => document.getElementById(id);
  const store = () => (typeof db !== 'undefined' ? db : null);
  let lockedKey = '';
  let lockUntil = 0;

  function same(a,b){ return String(a ?? '') === String(b ?? ''); }
  function reqByKey(key){
    const k=String(key||'');
    return (store()?.requirements||[]).find(r => [r.id,r.serverId,r.requirementId,r.profileKey].some(v=>same(v,k))) || null;
  }
  function optionValueFor(select, r, key){
    if(!select) return '';
    const candidates=[r?.id,r?.serverId,r?.requirementId,r?.profileKey,key].filter(Boolean).map(String);
    return candidates.find(v=>[...select.options].some(o=>o.value===v)) || '';
  }
  function applySelection(key){
    const r=reqByKey(key);
    const screen=$('screenRequirement');
    if(!r || !screen) return false;
    const value=optionValueFor(screen,r,key);
    if(!value) return false;
    if(screen.value!==value){
      screen.value=value;
      screen.dispatchEvent(new Event('change',{bubbles:true}));
    } else {
      try{ if(typeof updateSelectedRequirement==='function') updateSelectedRequirement(); }catch{}
    }
    const top=$('topRequirementSelect');
    if(top){
      const topValue=optionValueFor(top,r,key);
      if(topValue && top.value!==topValue){
        top.value=topValue;
        top.dispatchEvent(new Event('change',{bubbles:true}));
      }
    }
    try{ sessionStorage.setItem('tss_screen_requirement_key', String(r.serverId||r.id||key)); }catch{}
    return true;
  }
  function holdSelection(key){
    lockedKey=String(key||''); lockUntil=Date.now()+2200;
    [0,30,90,180,350,650,1100,1800].forEach(ms=>setTimeout(()=>{
      if(Date.now()<=lockUntil && lockedKey) applySelection(lockedKey);
    },ms));
  }
  function launch(button){
    const key=button?.dataset?.id || button?.dataset?.req || button?.closest('.req-card')?.querySelector('[data-id]')?.dataset?.id;
    const r=reqByKey(key);
    if(!r) return false;
    lockedKey=String(r.serverId||r.id||key);
    try{ if(typeof gotoView==='function') gotoView('screening'); }catch{}
    holdSelection(lockedKey);
    return true;
  }

  document.addEventListener('click',e=>{
    const btn=e.target.closest('.screen-req');
    if(!btn) return;
    // Capture the intended requirement before any older click handler can overwrite it.
    e.preventDefault();
    e.stopImmediatePropagation();
    launch(btn);
  },true);

  // Do not fight genuine user changes after the short navigation lock expires.
  document.addEventListener('change',e=>{
    if(e.target?.id==='screenRequirement' && Date.now()>lockUntil){
      lockedKey='';
      try{ sessionStorage.setItem('tss_screen_requirement_key', e.target.value||''); }catch{}
    }
  });

  window.TSSRequirementScreeningSelectionFix={applySelection,launch};
})();

