function syncLocalActivities(){if(activitySyncPromise)return activitySyncPromise;if(!me||!client())return Promise.resolve();const d=localDB();if(!d?.activity?.length)return Promise.resolve();const key='tss_report_activity_synced_v2';let seen=[];try{seen=JSON.parse(localStorage.getItem(key)||'[]')}catch{}const set=new Set(seen),pending=d.activity.filter(a=>{if(/^Candidate screened$/i.test(String(a.title||'')))return false;const f=`${a.date}|${a.title}|${a.detail}`;a.__fp=f;return!set.has(f)}).slice(-30);pending.forEach(a=>set.add(a.__fp));try{localStorage.setItem(key,JSON.stringify([...set].slice(-1000)))}catch{}activitySyncPromise=pending.reduce((p,a)=>p.then(()=>logActivity(a.title,'workspace','',{detail:a.detail,source:'browser_workspace',occurred_at:a.date})),Promise.resolve()).finally(()=>{activitySyncPromise=null});return activitySyncPromise}
